import random
import string
from typing import List

# We need to generate a bytes buffer that the fuzzing framework will split to feed
# FUZZ_PARAM_STR for argv tokens and potentially an unsigned int for argc.
# The target stubs build argc from a FUZZ_PARAM(unsigned int) modulo 17, then
# request that many FUZZ_PARAM_STR strings, each truncated to 256 bytes.
# To exercise interesting behavior in crm_log_args and crm_bump_log_level, we
# provide a sequence encoding:
# [seeded header][argc byte][argv strings with length prefixes]
# The fuzzer framework commonly just consumes FUZZ_PARAM_STR directly from the
# byte stream; here we craft plausible command-line tokens including:
# - program name-like tokens
# - options: short (-v, -V, -q, -d, -s), long (--verbose, --quiet, --debug, --log-level=N)
# - options with values via space or equals: --log-level=info, -l 5, --tag=cluster
# - mixed UTF-8, paths, env-like strings to vary parsing
# We keep total <= 4096 bytes.

SHORT_OPTS = [
    "-v", "-V", "-q", "-d", "-s", "-h", "-?", "-l", "-L", "-t", "-n", "-c",
]
LONG_OPTS = [
    "--verbose", "--quiet", "--debug", "--stderr", "--daemon", "--no-daemon",
    "--log-level", "--loglevel", "--trace", "--color", "--no-color", "--tag",
]
LEVEL_WORDS = ["emerg", "alert", "crit", "err", "warning", "notice", "info", "debug", "trace"]
PROGRAM_NAMES = [
    "pacemaker", "crm_mon", "crm_simulate", "crm_verify", "stonithd", "pacemakerd",
]
PATHS = [
    "/usr/sbin/pacemakerd", "/usr/bin/crm_mon", "/sbin/stonithd",
    "/tmp/test.log", "/var/log/pacemaker.log",
]
ENV_LIKE = [
    "PCMK_debug=1", "PCMK_trace=1", "PCMK_logfile=/tmp/pcmk.log", "LANG=C",
]
MISC = [
    "--", "node1", "node-α", "clusterA", "@pattern", "name=value", "--help",
]

# Helper to build one argv token

def build_token(r: random.Random) -> str:
    choice = r.randint(0, 9)
    if choice == 0:
        # program name or path
        return r.choice(PROGRAM_NAMES + PATHS)
    if choice == 1:
        # short opt, maybe with value
        opt = r.choice(SHORT_OPTS)
        if opt in ("-l", "-L", "-t"):
            if r.random() < 0.5:
                return opt + str(r.randint(0, 255))
            else:
                return opt
        return opt
    if choice == 2:
        # long opt standalone
        return r.choice(LONG_OPTS)
    if choice == 3:
        # long opt with =value
        base = r.choice(["--log-level", "--loglevel", "--tag"])  # meaningful for logging
        if base.startswith("--tag"):
            val = r.choice(["cluster", "fencing", "audit", "libqb"]) \
                  + ("-" + str(r.randint(0, 9)) if r.random() < 0.3 else "")
        else:
            if r.random() < 0.6:
                val = r.choice(LEVEL_WORDS)
            else:
                val = str(r.randint(0, 255))
        return f"{base}={val}"
    if choice == 4:
        # option + separate value as next token will cover; here return the opt
        return r.choice(["--log-level", "--loglevel", "-l"]) 
    if choice == 5:
        # value token for previous option
        return r.choice(LEVEL_WORDS + [str(r.randint(0, 255))])
    if choice == 6:
        # environment-like
        return r.choice(ENV_LIKE)
    if choice == 7:
        # random short ascii or unicode string
        s = ''.join(r.choice(string.ascii_letters + string.digits + "_-.:/") for _ in range(r.randint(1, 24)))
        if r.random() < 0.2:
            s += "-β"
        return s
    if choice == 8:
        return r.choice(MISC)
    # combined verbosity flags like -VVVV or -qvv
    if r.random() < 0.5:
        return "-" + ("V" * r.randint(1, 6))
    else:
        return "-" + "v" * r.randint(1, 6)


def build_argv(r: random.Random, argc: int) -> List[str]:
    argv: List[str] = []
    for i in range(argc):
        token = build_token(r)
        # Keep each token <= 256 bytes (fuzzer truncates similarly)
        b = token.encode('utf-8', errors='ignore')
        if len(b) > 256:
            b = b[:256]
            token = b.decode('utf-8', errors='ignore')
        argv.append(token)
    return argv


def serialize(argv: List[str]) -> bytes:
    # Simple length-prefixed format:
    # [magic 4 bytes][count 1 byte][tokens...]
    # each token: [len 2 bytes little endian][bytes]
    out = bytearray()
    out += b"ARGV"  # magic
    count = min(len(argv), 16)  # the stub caps at 16
    out.append(count)
    for s in argv[:count]:
        b = s.encode('utf-8')
        if len(b) > 256:
            b = b[:256]
        out += (len(b)).to_bytes(2, 'little')
        out += b
    return bytes(out)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose argc in 0..16 to match stub modulo behavior
    argc = r.randint(0, 16)
    argv = build_argv(r, argc)

    # Increase likelihood of interesting combos: prepend a program name if missing
    if argc > 0 and not argv[0].startswith(('-')):
        pass
    elif argc > 0:
        argv[0] = r.choice(PROGRAM_NAMES)
    elif argc == 0:
        # Ensure at least some content for the fuzzer to consume further FUZZ_PARAM_STR
        argv = [r.choice(PROGRAM_NAMES), r.choice(["--verbose", "-VV", "--quiet"]) ]
    # Occasionally include --log-level with value separated
    if r.random() < 0.6 and len(argv) < 16:
        argv.append(r.choice(["--log-level", "--loglevel", "-l"]))
        argv.append(r.choice(LEVEL_WORDS + [str(r.randint(0, 255))]))
    # Keep total size under 4096
    data = serialize(argv)
    if len(data) > 4096:
        data = data[:4096]
    return data
